(()=>{const listening=location.pathname.startsWith("/cet4");document.body.classList.add(listening?"stone-listening":"stone-home");let preferences={};try{preferences=JSON.parse(localStorage.getItem("stone-ui-v2")||"{}")}catch{}const save=()=>{try{localStorage.setItem("stone-ui-v2",JSON.stringify(preferences))}catch{}};const apply=()=>{for(const name of["words","story","listening"])document.documentElement.style.setProperty("--stone-"+name+"-size",Math.max(16,Math.min(24,Number(preferences[name])||18))+"px")};window.StoneUI={get spaceSubmit(){return preferences.spaceSubmit===true}};apply();const dialog=document.createElement("dialog");dialog.id="stonePreferences";dialog.setAttribute("aria-labelledby","stonePreferencesTitle");dialog.innerHTML=`<div class="stone-dialog-heading"><h2 id="stonePreferencesTitle">阅读与学习设置</h2><button type="button" data-close aria-label="关闭设置">×</button></div>\n    <p class="stone-muted">按你的习惯调整，关闭后自动保存。</p>\n    <section class="stone-preference-section"><h3>阅读字号</h3>${[["words","词库"],["story","小说"],["listening","精听"]].map(([key,label])=>`<div class="stone-size-row"><span>${label}</span><button data-size="${key}" data-step="-1" aria-label="缩小${label}字号">A−</button><output id="stoneSize-${key}" aria-live="polite"></output><button data-size="${key}" data-step="1" aria-label="放大${label}字号">A+</button></div>`).join("")}</section>\n    <section class="stone-preference-section"><h3>外观与声音</h3><div id="stoneAppearance"></div></section>\n    ${listening?'<section class="stone-preference-section"><label class="stone-check"><input type="checkbox" id="stoneSpaceSubmit">空格提交（极速练习）</label><p class="stone-muted">默认用 Enter 或「验证」。开启后，物理空格键也可提交；输入法自动补空格不会提交。</p></section>':""}\n    <details class="stone-shortcut-help"><summary>键盘操作</summary><p>${listening?"Enter：提交当前答案；输入框以外 Space：播放 / 暂停。":"/：搜索；词典中 ← / →：切词，Space：发音，+ / −：标记；小说 A / B / C：答题。"}<br>Esc：关闭当前面板。?：打开本设置。</p></details>\n    ${!listening?'<button type="button" id="stoneAdvanced">高级设置</button>':""}`;document.body.append(dialog);const updateLabels=()=>{for(const key of["words","story","listening"]){const size=Math.max(16,Math.min(24,Number(preferences[key])||18));document.getElementById("stoneSize-"+key).textContent=size+" px";dialog.querySelector(`[data-size="${key}"][data-step="-1"]`).disabled=size<=16;dialog.querySelector(`[data-size="${key}"][data-step="1"]`).disabled=size>=24}};updateLabels();dialog.querySelector("[data-close]").onclick=()=>dialog.close();dialog.addEventListener("click",e=>{const b=e.target.closest("[data-size]");if(!b)return;const key=b.dataset.size;preferences[key]=Math.max(16,Math.min(24,(Number(preferences[key])||18)+Number(b.dataset.step)));apply();updateLabels();save()});const appearance=document.getElementById("stoneAppearance");for(const id of listening?["themeToggleBtn"]:["themeBtn","audioBtn"]){const button=document.getElementById(id);if(button){appearance.append(button);button.classList.add("stone-setting-icon");button.setAttribute("aria-label",id==="audioBtn"?"切换学习音效":"切换明暗主题");const label=document.createElement("span");label.textContent=id==="audioBtn"?"学习音效":"明暗主题";appearance.append(label)}}const space=document.getElementById("stoneSpaceSubmit");if(space){space.checked=preferences.spaceSubmit===true;space.onchange=()=>{preferences.spaceSubmit=space.checked;save()}}document.getElementById("stoneAdvanced")?.addEventListener("click",()=>{dialog.close();openSettingsModal()});let opener=document.getElementById("settingsBtn");if(!opener){opener=document.createElement("button");opener.className="paper-icon-btn";opener.id="stoneSettingsBtn";opener.textContent="⚙";document.querySelector(".header-controls").append(opener)}opener.removeAttribute("onclick");opener.setAttribute("aria-label","阅读与学习设置");opener.title="阅读与学习设置";opener.onclick=()=>{updateLabels();dialog.showModal()};window.addEventListener("keydown",e=>{if(e.isComposing||e.ctrlKey||e.metaKey||e.altKey||e.repeat)return;const typing=e.target.closest?.('input,textarea,select,[contenteditable="true"]');if(e.key==="?"&&!typing&&!dialog.open){e.preventDefault();dialog.showModal()}if(listening&&e.code==="Space"&&!typing&&!dialog.open&&!e.target.closest?.("button,a,summary")){e.preventDefault();document.getElementById("mainPlayBtn")?.click()}});const keyboardState=()=>{const editing=!!document.activeElement?.matches('input,textarea,[contenteditable="true"]');const compressed=window.visualViewport&&window.innerHeight-window.visualViewport.height>140;document.body.classList.toggle("stone-keyboard-open",!!(editing&&compressed))};window.visualViewport?.addEventListener("resize",keyboardState);document.addEventListener("focusin",keyboardState);document.addEventListener("focusout",()=>setTimeout(keyboardState,0))})();